    global $stdin;
    $line = fgets($stdin);
    $parts = preg_split('/\s+/', trim($line));
    $parts = array_filter($parts, function($s) { return $s !== ''; });
    return array_map('intval', $parts);
}

function readLongArray() {
    global $stdin;
    $line = fgets($stdin);
    $parts = preg_split('/\s+/', trim($line));
    $parts = array_filter($parts, function($s) { return $s !== ''; });
    return array_map('intval', $parts);
}

