    $stdin = fopen($_inputFilename, 'r');
    $stdout = fopen($_outputFilename, 'w');
    ob_start();
    solution();
    $output = ob_get_clean();
    fwrite($stdout, $output);
    fclose($stdin);
    fclose($stdout);
} else {
    $stdin = fopen('php://stdin', 'r');
    solution();
    fclose($stdin);
}
